-- Catalog only. No application relation reads or function execution.
WITH objects AS (
 SELECT 'relation' kind, c.relname key, jsonb_build_object('kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'owner',pg_get_userbyid(c.relowner)) value
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S','f')
 UNION ALL SELECT 'column', c.relname||'.'||a.attname, jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default_hash',md5(coalesce(pg_get_expr(d.adbin,d.adrelid),'')))
 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum
 WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','f') AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'constraint', c.relname||'.'||x.conname, jsonb_build_object('type',x.contype,'validated',x.convalidated,'definition_hash',md5(pg_get_constraintdef(x.oid,true))) FROM pg_constraint x JOIN pg_class c ON c.oid=x.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
 UNION ALL SELECT 'policy', schemaname||'.'||tablename||'.'||policyname, jsonb_build_object('permissive',permissive,'roles',roles,'cmd',cmd,'using_hash',md5(coalesce(qual,'')),'check_hash',md5(coalesce(with_check,''))) FROM pg_policies WHERE schemaname='public'
 UNION ALL SELECT 'index', tablename||'.'||indexname, jsonb_build_object('definition_hash',md5(indexdef)) FROM pg_indexes WHERE schemaname='public'
 UNION ALL SELECT 'function', p.proname||'('||pg_get_function_identity_arguments(p.oid)||')', jsonb_build_object('definer',p.prosecdef,'config',p.proconfig,'owner',pg_get_userbyid(p.proowner),'language',l.lanname,'volatility',p.provolatile,'definition_hash',md5(pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.prokind IN ('f','p')
 UNION ALL SELECT 'trigger', c.relname||'.'||t.tgname, jsonb_build_object('enabled',t.tgenabled,'definition_hash',md5(pg_get_triggerdef(t.oid,true))) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal
 UNION ALL SELECT 'view', c.relname, jsonb_build_object('definition_hash',md5(pg_get_viewdef(c.oid,true))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m')
 UNION ALL SELECT 'relation_acl', c.relname||':'||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END||':'||a.privilege_type||':'||pg_get_userbyid(a.grantor), jsonb_build_object('grantable',a.is_grantable) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 'S'::"char" ELSE 'r'::"char" END,c.relowner))) a WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S','f')
 UNION ALL SELECT 'function_acl', p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END||':'||a.privilege_type||':'||pg_get_userbyid(a.grantor), jsonb_build_object('grantable',a.is_grantable) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='public' AND p.prokind IN ('f','p')
 UNION ALL SELECT 'schema_acl', n.nspname||':'||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END||':'||a.privilege_type, jsonb_build_object('grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='public'
 UNION ALL SELECT 'default_acl', pg_get_userbyid(d.defaclrole)||':'||coalesce(n.nspname,'ALL_SCHEMAS')||':'||d.defaclobjtype::text||':'||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END||':'||a.privilege_type, jsonb_build_object('grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl) a WHERE n.nspname='public' OR d.defaclnamespace=0
 UNION ALL SELECT 'enum', t.typname||':'||e.enumsortorder, jsonb_build_object('label',e.enumlabel) FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public'
 UNION ALL SELECT 'column_acl', c.relname||'.'||x.attname||':'||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END||':'||a.privilege_type, jsonb_build_object('grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) FROM pg_attribute x JOIN pg_class c ON c.oid=x.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(x.attacl) a WHERE n.nspname='public' AND x.attnum>0 AND NOT x.attisdropped
)
SELECT jsonb_build_object('format',1,'scope','public-catalog-v1','postgres_version',current_setting('server_version'),'objects',coalesce(jsonb_agg(jsonb_build_object('kind',kind,'key',key,'value',value) ORDER BY kind,key),'[]'::jsonb)) AS snapshot FROM objects;
